#### graph topological order

```cpp
#include <unordered_map>
#include <vector>
#include <tuple>
#include <string>

std::string topologicalOrder(std::unordered_map<int, std::vector<int>> graph) {
  std::unordered_map<int, int> numParents;

  for (auto [node, neighbors] : graph) {
    if (numParents.count(node) == 0) {
      numParents[node] = 0;
    }

    for (int neighbor : neighbors) {
      numParents[neighbor] += 1;
    }
  }

  std::vector<int> ready;

  for (auto [node, count] : numParents) {
    if (count == 0) {
      ready.push_back(node);
    }
  }

  std::string order = "";
  while (ready.size() > 0) {
    int node = ready.back();
    order += std::to_string(node);
    ready.pop_back();

    for (int child : graph[node]) {
      numParents[child] -= 1;

      if (numParents[child] == 0) {
        ready.push_back(child);
      }
    }
  }

  return order;
}

std::string safeCracking(std::vector<std::tuple<int, int>> hints) {
  std::unordered_map<int, std::vector<int>> graph;
  for (auto [a, b] : hints) {
    graph[a].push_back(b);
  }
  return topologicalOrder(graph);
}
```

